style.css:
@-moz-document domain("batcave.biz") {
/* ==========================================================
     1. HIGH-TECH TERMINAL VARIABLE SYSTEM
     ========================================================== */
  :root {
    /* Translucent slate colors to let the background animation subtly peek through */
    --bg-main-flat: #0b0f19 !important;
    --bg-panel: rgba(15, 23, 42, 0.85) !important;
    --bg-card: rgba(30, 41, 59, 0.65) !important;
    --border: #334155 !important;
    --text-primary: #f8fafc !important;
    --text-secondary: #94a3b8 !important;
    --accent: #facc15 !important; /* Bat-Signal Yellow */
    --glow: rgba(250, 204, 21, 0.2) !important;
  }

  /* ==========================================================
     2. THE ANIMATED BATCAVE GIF INJECTION
     ========================================================== */
  body, html, #page-wrapper, .main-content {
    /* 
       The linear-gradient layer acts as a 'tint shield' on top of the GIF.
       This darkens the animation so your bright text remains perfectly readable.
    */
    background-image: linear-gradient(
        to bottom,
        rgba(11, 15, 25, 0.85), 
        rgba(15, 23, 42, 0.92)
      ), 
      url('https://giphy.com') !important;
    
    background-size: cover !important;
    background-position: center center !important;
    background-attachment: fixed !important;
    background-repeat: no-repeat !important;
    color: var(--text-primary) !important;
  }

  /* ==========================================================
     3. INTERFACE ELEMENTS & CONTAINERS OVERRIDE
     ========================================================== */
  
  /* Frosted Glass Layering for Cards & Filters (The boxes in your screenshot) */
  .comic-card, .manga-box, .card, .panel, .list-group-item, 
  [class*="filter"], [class*="container-"], .notification-settings,
  div[style*="background-color"] {
    background-color: var(--bg-card) !important;
    border: 1px solid var(--border) !important;
    border-radius: 10px !important;
    /* Softly blurs the moving GIF behind your menus for premium legibility */
    backdrop-filter: blur(8px) webkit-backdrop-filter(8px) !important;
    transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease !important;
  }

  /* Interactive Hover Glow */
  .comic-card:hover, .manga-box:hover {
    border-color: var(--accent) !important;
    box-shadow: 0 8px 24px var(--glow) !important;
    transform: translateY(-2px) !important;
  }

  /* Top Navigation Bars, Search Bars, and Header Structural Bars */
  header, nav, .navbar, .sidebar, .top-bar, #top-nav {
    background-color: var(--bg-panel) !important;
    border-bottom: 1px solid var(--border) !important;
    backdrop-filter: blur(12px) webkit-backdrop-filter(12px) !important;
  }

  /* Typography, Titles, and Counters */
  h1, h2, h3, h4, .title, .logo-text, strong, .tracked-count {
    color: var(--text-primary) !important;
    text-shadow: 0 2px 4px rgba(0, 0, 0, 0.6) !important;
  }

  a, .accent-text, [class*="link"] {
    color: var(--accent) !important;
  }

  p, .text-muted, .meta-data, .timestamp, [class*="secondary"] {
    color: var(--text-secondary) !important;
  }

  /* Action Buttons (Unsubscribe / Subscribe to updates) */
  .btn, .btn-primary, button, input[type="submit"], [class*="button"] {
    background-color: var(--border) !important;
    color: var(--text-primary) !important;
    border: 1px solid rgba(255, 255, 255, 0.05) !important;
    border-radius: 6px !important;
    font-weight: 600 !important;
    transition: all 0.2s ease !important;
  }

  /* Make buttons illuminate beautifully when hovered over */
  button:hover, .btn:hover, [class*="button"]:hover {
    background-color: var(--accent) !important;
    color: var(--bg-main-flat) !important;
    box-shadow: 0 0 12px rgba(250, 204, 21, 0.4) !important;
  }
}
